### Adding Structured Logging
Since you don't currently have a logging library, the standard practice in the Node.js ecosystem is to use **Pino**. It is high-performance and outputs JSON, which is the standard for structured logging.

#### 1. Install Pino
```bash
npm install pino
```

#### 2. Update `src/server.js`
Here is the diff to implement structured logging.

```diff
--- a/src/server.js
+++ b/src/server.js
@@ -1,15 +1,24 @@
 import express from 'express';
+import pino from 'pino';
 import { config } from './config.js';
 import { healthcheck } from './db.js';
 import { chargeInvoice } from './billing.js';

+const logger = pino({ level: config.logLevel });
 const app = express();
 app.use(express.json());

+// Simple request logging middleware
+app.use((req, res, next) => {
+  logger.info({ method: req.method, url: req.url }, 'incoming request');
+  next();
+});
+
 app.get('/healthz', async (_req, res) => {
   try {
     await healthcheck();
     res.json({ ok: true });
   } catch (err) {
+    logger.error({ err }, 'healthcheck failed');
     res.status(503).json({ ok: false, error: err.message });
   }
 });
@@ -17,7 +26,12 @@
 app.post('/invoices/:id/charge', async (req, res) => {
-  const result = await chargeInvoice(req.params.id);
-  res.json(result);
+  try {
+    const result = await chargeInvoice(req.params.id);
+    logger.info({ invoiceId: req.params.id }, 'invoice charged successfully');
+    res.json(result);
+  } catch (err) {
+    logger.error({ err, invoiceId: req.params.id }, 'failed to charge invoice');
+    res.status(500).json({ error: 'Internal server error' });
+  }
 });

 app.listen(config.port, () => {
-  console.log(`orbital-invoices listening on ${config.port}`);
+  logger.info(`orbital-invoices listening on ${config.port}`);
 });
```

### Why this approach?
*   **Middleware:** The `app.use` block captures every incoming request with its method and URL, which is essential for debugging traffic patterns.
*   **Error Context:** By passing `{ err }` to the logger, Pino automatically serializes the error object (including stack traces) into the JSON output.
*   **Contextual Data:** In the `/charge` route, we log the `invoiceId` alongside the event, allowing you to filter logs by specific invoice IDs in your log aggregator (like Datadog, CloudWatch, or ELK).
